t.script:
(function() {
    var STORAGE_KEY = 'misa_sale_status_code';
    var PAGE_SIZE = 50;
    var STATE_LABELS = {not_checked: 'Chưa kiểm tra', missing: 'Chưa có đề nghị xuất HĐ', requested: 'Đã đề nghị, chờ HĐ', invoiced: 'Đã xuất hóa đơn'};
    var state = {
        salerCode: localStorage.getItem(STORAGE_KEY) || '',
        search: '', onlyPending: true, page: 1, total: 0, rows: [], selected: {},
    };

    function esc(s) {
        var d = document.createElement('div');
        d.textContent = s == null ? '' : String(s);
        return d.innerHTML;
    }
    function fmtMoney(n) {
        if (!n) { return '0 đ'; }
        return Math.round(n).toLocaleString('vi-VN') + ' đ';
    }
    function rpc(url, params) {
        return fetch(url, {
            method: 'POST', headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({jsonrpc: '2.0', method: 'call', params: params || {}}),
        }).then(function(r) { return r.json(); }).then(function(j) {
            if (j.error) {
                var msg = (j.error.data && j.error.data.message) || j.error.message || 'Có lỗi xảy ra';
                throw new Error(msg);
            }
            if (j.result && j.result.status === 'error') {
                throw new Error(j.result.message || 'Có lỗi xảy ra');
            }
            return j.result;
        });
    }
    function toast(message, type) {
        var stack = document.getElementById('msu-toast-stack');
        var el = document.createElement('div');
        el.className = 'msu-toast' + (type ? ' ' + type : '');
        el.textContent = message;
        stack.appendChild(el);
        setTimeout(function() { el.remove(); }, 5000);
    }

    var selectEl = document.getElementById('msu-saler-select');
    var appEl = document.getElementById('msu-app');
    var hintEl = document.getElementById('msu-identity-hint');

    function loadSalerCodes() {
        return rpc('/misa_sale_status/api/saler_codes').then(function(res) {
            var codes = res.codes || [];
            codes.forEach(function(code) {
                var opt = document.createElement('option');
                opt.value = code;
                opt.textContent = code;
                selectEl.appendChild(opt);
            });
            if (state.salerCode && codes.indexOf(state.salerCode) !== -1) {
                selectEl.value = state.salerCode;
                onSalerChosen();
            } else if (state.salerCode) {
                hintEl.textContent = 'Mã "' + state.salerCode + '" đã lưu trước đó không còn hợp lệ, vui lòng chọn lại.';
                state.salerCode = '';
                localStorage.removeItem(STORAGE_KEY);
            }
        }).catch(function(e) { toast('Lỗi tải danh sách mã sale: ' + e.message, 'error'); });
    }

    function onSalerChosen() {
        appEl.style.display = state.salerCode ? '' : 'none';
        hintEl.textContent = '';
        if (state.salerCode) {
            loadList(1);
        }
    }

    selectEl.addEventListener('change', function() {
        state.salerCode = selectEl.value;
        state.selected = {};
        if (state.salerCode) {
            localStorage.setItem(STORAGE_KEY, state.salerCode);
        } else {
            localStorage.removeItem(STORAGE_KEY);
        }
        onSalerChosen();
    });

    function rowMeta(row) {
        var parts = [];
        if (row.multi_order_group) { parts.push('<i class="fa fa-sitemap msu-link-icon" title="Gộp chung nhiều đơn bán: ' + esc(row.group_order_names) + '"/>'); }
        if (row.master_picking_id || (row.covered_pickings && row.covered_pickings.length)) { parts.push('<i class="fa fa-link msu-link-icon" title="Gộp chung đề nghị xuất HĐ với phiếu khác"/>'); }
        return parts.join('');
    }

    function renderRows() {
        var tbody = document.getElementById('msu-tbody');
        tbody.innerHTML = '';
        document.getElementById('msu-empty').style.display = state.rows.length ? 'none' : '';
        state.rows.forEach(function(row) {
            var tr = document.createElement('tr');
            var checked = state.selected[row.id] ? 'checked="checked"' : '';
            var manualHtml = row.manual_refno
                ? '<span class="msu-manual-refno" title="Đã gắn mã đề nghị thủ công">' + esc(row.manual_refno) + '</span>'
                : '<span class="text-muted">—</span>';
            var exceptionHtml = row.exception
                ? '<span class="msu-badge-exception" title="' + esc(row.exception_reason || '') + '">Ngoại lệ</span>' : '';
            tr.innerHTML =
                '<td><input type="checkbox" class="msu-row-check" data-id="' + row.id + '" ' + checked + '/></td>' +
                '<td><b>' + esc(row.name) + '</b>' + rowMeta(row) + '<br/><span class="text-muted small">' + esc(row.sale_order_name || '') + '</span></td>' +
                '<td>' + esc(row.partner_name) + '</td>' +
                '<td>' + esc(row.date_done) + '</td>' +
                '<td class="text-end">' + fmtMoney(row.actual_amount) + '</td>' +
                '<td><span class="msu-badge-state msu-badge-state-' + row.state + '">' + esc(row.state_label) + '</span> ' + exceptionHtml + '</td>' +
                '<td>' + manualHtml + '</td>' +
                '<td><div class="msu-row-actions">' +
                    '<button class="btn btn-sm btn-outline-primary msu-act-check" data-id="' + row.id + '">Kiểm tra ngay</button>' +
                    (row.state !== 'invoiced' ? '<button class="btn btn-sm btn-outline-secondary msu-act-link" data-id="' + row.id + '" data-name="' + esc(row.name) + '">Gắn mã đề nghị</button>' : '') +
                    (row.state !== 'invoiced' && !row.exception ? '<button class="btn btn-sm btn-outline-danger msu-act-exception" data-id="' + row.id + '" data-name="' + esc(row.name) + '">Ngoại lệ</button>' : '') +
                    (row.exception ? '<button class="btn btn-sm btn-outline-secondary msu-act-unexception" data-id="' + row.id + '">Bỏ ngoại lệ</button>' : '') +
                '</div></td>';
            tbody.appendChild(tr);
        });
        bindRowEvents();
        updateBulkBar();
    }

    function updateBadges(counts) {
        counts = counts || {};
        document.getElementById('msu-count-missing').textContent = counts.missing || 0;
        document.getElementById('msu-count-requested').textContent = counts.requested || 0;
        document.getElementById('msu-count-exception').textContent = counts.exception || 0;
        document.getElementById('msu-count-invoiced').textContent = counts.invoiced || 0;
    }

    function updatePagination() {
        var totalPages = Math.max(1, Math.ceil(state.total / PAGE_SIZE));
        var pag = document.getElementById('msu-pagination');
        pag.style.display = state.total > PAGE_SIZE ? '' : 'none';
        document.getElementById('msu-page-label').textContent = 'Trang ' + state.page + ' / ' + totalPages + ' (' + state.total + ' phiếu)';
        document.getElementById('msu-prev').disabled = state.page <= 1;
        document.getElementById('msu-next').disabled = state.page >= totalPages;
    }

    function loadList(page, opts) {
        opts = opts || {};
        if (!state.salerCode) { return Promise.resolve(); }
        state.page = page;
        return rpc('/misa_sale_status/api/list', {
            saler_code: state.salerCode, search: state.search,
            only_pending: state.onlyPending, limit: PAGE_SIZE, offset: (page - 1) * PAGE_SIZE,
        }).then(function(res) {
            var data = res.data || {};
            state.rows = data.rows || [];
            state.total = data.total || 0;
            state.selected = {};
            updateBadges(data.counts);
            renderRows();
            updatePagination();
        }).catch(function(e) {
            if (!opts.silent) { toast('Lỗi tải danh sách: ' + e.message, 'error'); }
        });
    }

    document.getElementById('msu-search-btn').addEventListener('click', function() {
        state.search = document.getElementById('msu-search').value.trim();
        document.getElementById('msu-search-clear').style.display = state.search ? '' : 'none';
        loadList(1);
    });
    document.getElementById('msu-search').addEventListener('keydown', function(ev) {
        if (ev.key === 'Enter') { document.getElementById('msu-search-btn').click(); }
    });
    document.getElementById('msu-search-clear').addEventListener('click', function() {
        state.search = '';
        document.getElementById('msu-search').value = '';
        this.style.display = 'none';
        loadList(1);
    });
    document.getElementById('msu-only-pending').addEventListener('change', function() {
        state.onlyPending = this.checked;
        loadList(1);
    });
    document.getElementById('msu-refresh-btn').addEventListener('click', function() { loadList(state.page); });
    document.getElementById('msu-prev').addEventListener('click', function() { if (state.page > 1) { loadList(state.page - 1); } });
    document.getElementById('msu-next').addEventListener('click', function() {
        if (state.page < Math.ceil(state.total / PAGE_SIZE)) { loadList(state.page + 1); }
    });

    document.getElementById('msu-select-all').addEventListener('change', function() {
        var checked = this.checked;
        state.rows.forEach(function(row) {
            if (checked) { state.selected[row.id] = true; } else { delete state.selected[row.id]; }
        });
        renderRows();
    });

    function bindRowEvents() {
        document.querySelectorAll('.msu-row-check').forEach(function(cb) {
            cb.addEventListener('change', function() {
                var id = parseInt(this.dataset.id, 10);
                if (this.checked) { state.selected[id] = true; } else { delete state.selected[id]; }
                updateBulkBar();
            });
        });
        document.querySelectorAll('.msu-act-check').forEach(function(btn) {
            btn.addEventListener('click', function() { runCheck([parseInt(this.dataset.id, 10)]); });
        });
        document.querySelectorAll('.msu-act-link').forEach(function(btn) {
            btn.addEventListener('click', function() { openLinkModal(parseInt(this.dataset.id, 10), this.dataset.name); });
        });
        document.querySelectorAll('.msu-act-exception').forEach(function(btn) {
            btn.addEventListener('click', function() { openExceptionModal([parseInt(this.dataset.id, 10)], this.dataset.name); });
        });
        document.querySelectorAll('.msu-act-unexception').forEach(function(btn) {
            btn.addEventListener('click', function() { runUnexception([parseInt(this.dataset.id, 10)]); });
        });
    }

    function updateBulkBar() {
        var ids = Object.keys(state.selected).map(Number);
        var bar = document.getElementById('msu-bulk-bar');
        bar.style.display = ids.length ? '' : 'none';
        document.getElementById('msu-bulk-count').textContent = 'Đã chọn ' + ids.length + ' phiếu';
    }

    function runCheck(ids) {
        rpc('/misa_sale_status/api/check', {picking_ids: ids, saler_code: state.salerCode}).then(function() {
            toast('Đã kiểm tra xong ' + ids.length + ' phiếu.', 'success');
            loadList(state.page);
        }).catch(function(e) { toast('Lỗi kiểm tra MISA: ' + e.message, 'error'); });
    }
    function runUnexception(ids) {
        rpc('/misa_sale_status/api/unmark_exception', {picking_ids: ids, saler_code: state.salerCode}).then(function() {
            toast('Đã bỏ đánh dấu ngoại lệ.', 'success');
            loadList(state.page);
        }).catch(function(e) { toast('Lỗi: ' + e.message, 'error'); });
    }

    document.getElementById('msu-bulk-check').addEventListener('click', function() { runCheck(Object.keys(state.selected).map(Number)); });
    document.getElementById('msu-bulk-unexception').addEventListener('click', function() { runUnexception(Object.keys(state.selected).map(Number)); });
    document.getElementById('msu-bulk-exception').addEventListener('click', function() {
        openExceptionModal(Object.keys(state.selected).map(Number), Object.keys(state.selected).length + ' phiếu đã chọn');
    });

    // ===== Modal: gắn mã đề nghị =====
    var linkModal = document.getElementById('msu-link-modal');
    var linkPickingId = null;
    function openLinkModal(id, name) {
        linkPickingId = id;
        document.getElementById('msu-link-picking-name').textContent = name;
        document.getElementById('msu-link-refno').value = '';
        document.getElementById('msu-link-error').textContent = '';
        linkModal.style.display = 'flex';
    }
    document.getElementById('msu-link-cancel').addEventListener('click', function() { linkModal.style.display = 'none'; });
    document.getElementById('msu-link-confirm').addEventListener('click', function() {
        var refno = document.getElementById('msu-link-refno').value.trim();
        var errEl = document.getElementById('msu-link-error');
        if (!refno) { errEl.textContent = 'Vui lòng nhập mã đề nghị.'; return; }
        rpc('/misa_sale_status/api/manual_link', {picking_id: linkPickingId, saler_code: state.salerCode, refno: refno}).then(function(res) {
            linkModal.style.display = 'none';
            if (res.warning) { toast(res.warning, 'warning'); } else { toast('Đã gắn mã đề nghị và xác nhận đã xuất hóa đơn.', 'success'); }
            loadList(state.page);
        }).catch(function(e) { errEl.textContent = e.message; });
    });

    // ===== Modal: đánh dấu ngoại lệ =====
    var exceptionModal = document.getElementById('msu-exception-modal');
    var exceptionIds = [];
    function openExceptionModal(ids, label) {
        exceptionIds = ids;
        document.getElementById('msu-exception-target').textContent = 'Phiếu: ' + label;
        document.getElementById('msu-exception-reason').value = '';
        document.getElementById('msu-exception-error').textContent = '';
        exceptionModal.style.display = 'flex';
    }
    document.getElementById('msu-exception-cancel').addEventListener('click', function() { exceptionModal.style.display = 'none'; });
    document.getElementById('msu-exception-confirm').addEventListener('click', function() {
        var reason = document.getElementById('msu-exception-reason').value.trim();
        var errEl = document.getElementById('msu-exception-error');
        if (!reason) { errEl.textContent = 'Vui lòng nhập lý do.'; return; }
        rpc('/misa_sale_status/api/mark_exception', {picking_ids: exceptionIds, saler_code: state.salerCode, reason: reason}).then(function() {
            exceptionModal.style.display = 'none';
            toast('Đã đánh dấu ngoại lệ.', 'success');
            loadList(state.page);
        }).catch(function(e) { errEl.textContent = e.message; });
    });

    loadSalerCodes();
    // Cảnh báo trong trang: tự làm mới định kỳ để badge/đếm luôn cập nhật kể cả
    // khi sale không thao tác gì (đóng vai trò "cảnh báo" theo yêu cầu, không
    // cần push notification trình duyệt).
    setInterval(function() {
        if (state.salerCode) { loadList(state.page, {silent: true}); }
    }, 60000);
})();
